    body: "The Ten Commandments remain central to Christian teaching, including instructions such as not stealing and honouring one's parents. A prophet in the Bible was someone who spoke God's message to the people, often calling them back to faithfulness.\n\nThe New Testament book of Acts of the Apostles describes the early history of the Christian Church after Jesus's resurrection, including how the message of Christianity spread to new communities.\n\nPaul is an important figure in the New Testament, known for travelling widely to spread the Christian message and for writing letters, called epistles, to various churches. These letters remain important to Christians today because they contain teachings and guidance for how to live as a Christian.\n\nStudying these figures and texts — the commandments, the prophets, Acts, and Paul's letters — gives a fuller picture of how the Christian faith developed and spread.",
